<h2>Calculate Overall Equipment Effectiveness (OEE)</h2><p class="lead">Break OEE into availability, performance and quality so the loss category is visible.</p>
<div class="form-grid"><div class="field"><label for="planned">Planned production time (minutes)</label><input id="planned" type="number" min="0.0001" step="any" value="480"></div><div class="field"><label for="down">Stop/downtime within planned time (minutes)</label><input id="down" type="number" min="0" step="any" value="60"></div><div class="field"><label for="ideal">Ideal cycle time (seconds/unit)</label><input id="ideal" type="number" min="0.0001" step="any" value="30"></div><div class="field"><label for="total">Total units</label><input id="total" type="number" min="0" step="any" value="720"></div><div class="field"><label for="good">Good units</label><input id="good" type="number" min="0" step="any" value="690"></div></div>
<div class="result-box"><div class="result-grid"><div class="metric"><span>Availability</span><strong id="a">—</strong></div><div class="metric"><span>Performance</span><strong id="p">—</strong></div><div class="metric"><span>Quality</span><strong id="q">—</strong></div><div class="metric"><span>OEE</span><strong id="oee">—</strong></div></div><div id="note" class="helper" style="margin-top:12px"></div></div>
<script>
(()=>{const $=id=>document.getElementById(id);function go(){const pt=+$('planned').value,d=+$('down').value,i=+$('ideal').value,t=+$('total').value,g=+$('good').value;if(!(pt>0&&d>=0&&d<=pt&&i>0&&t>=0&&g>=0&&g<=t)){['a','p','q','oee'].forEach(id=>$(id).textContent='—');$('note').textContent='Check that downtime ≤ planned time and good units ≤ total units.';$('note').className='helper danger';return}const run=pt-d,A=run/pt,P=run>0?(i*t)/(run*60):0,Q=t>0?g/t:0,O=A*P*Q;$('a').textContent=(A*100).toFixed(2)+'%';$('p').textContent=(P*100).toFixed(2)+'%';$('q').textContent=(Q*100).toFixed(2)+'%';$('oee').textContent=(O*100).toFixed(2)+'%';$('note').textContent=P>1?'Performance exceeds 100%. Verify ideal cycle time, units and runtime; an ideal cycle that is too slow commonly causes this.':'OEE = Availability × Performance × Quality. Use consistent Planned Production Time and ideal-cycle definitions.';$('note').className='helper'+(P>1?' danger':'')}['planned','down','ideal','total','good'].forEach(id=>$(id).addEventListener('input',go));go()})();
</script>
